    x, y = position

    # Basic neighbor positions
    neighbors = {
        (-1, 0): (x - 1, y),
        (1, 0):  (x + 1, y),
        (0, -1): (x, y - 1),
        (0, 1):  (x, y + 1)
    }

    # Avoid out-of-bounds moves
    def in_bounds(pos):
        px, py = pos
        return 0 <= px < width and 0 <= py < height

    # Determine step towards a target
    def move_towards(target_pos):
        tx, ty = target_pos
        dx = dy = 0
        if tx > x:
