            if in_bounds(candidate):
                obs_type = get_entity_type(candidate)
                if obs_type != 'obstacle':
                    return dx, 0
        if dy != 0:
            candidate = (x, y + dy)
            if in_bounds(candidate):
                obs_type = get_entity_type(candidate)
                if obs_type != 'obstacle':
